package com.bank.tree;

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.List;
import java.util.Queue;
import java.util.logging.Logger;

// Validates that an approval hierarchy is a tree: connected and acyclic.
public class ApprovalTreeValidator {

    private static final Logger log = Logger.getLogger(ApprovalTreeValidator.class.getName());

    public boolean isValidTree(int n, int[][] edges) {
        if (edges.length != n - 1) {       // tree identity: exactly n-1 edges
            log.info("Edge count " + edges.length + " != " + (n - 1) + " -> not a tree");
            return false;
        }
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int[] e : edges) {
            adj.get(e[0]).add(e[1]);
            adj.get(e[1]).add(e[0]);       // undirected
        }

        boolean[] visited = new boolean[n];
        Queue<Integer> queue = new ArrayDeque<>();
        queue.add(0);
        visited[0] = true;
        int count = 0;
        while (!queue.isEmpty()) {
            int node = queue.poll();
            count++;
            for (int nb : adj.get(node)) {
                if (!visited[nb]) {
                    visited[nb] = true;
                    queue.add(nb);
                }
            }
        }
        boolean connected = count == n;    // all nodes reachable?
        log.info("Reachable=" + count + "/" + n + " -> validTree=" + connected);
        return connected;
    }
}
