package com.bank.tree;

import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

public class TreeValidatorDemo {

    private static final Logger log = Logger.getLogger(TreeValidatorDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) {
            root.removeHandler(h);
        }
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        log.info("National Bank of India — Approval Hierarchy Validation");
        ApprovalTreeValidator validator = new ApprovalTreeValidator();

        // 5 units, 4 edges, connected → valid tree
        int[][] valid = {{0, 1}, {0, 2}, {0, 3}, {1, 4}};
        validator.isValidTree(5, valid);         // true

        // 4 units but a cycle 1-2-3-1 and node 0 isolated-ish → not a tree
        int[][] invalid = {{1, 2}, {2, 3}, {3, 1}};
        validator.isValidTree(4, invalid);       // false (edge count 3 != 3? here n-1=3, but cycle+disconnect)
    }
}
